struct ScopedHostValue {
  X3PackageHost* host;
  X3Value value;
  ~ScopedHostValue() {
    if (value.tag != X3_TAG_INVALID) host->value_release(value);
  }
  ScopedHostValue(const ScopedHostValue&) = delete;
  ScopedHostValue& operator=(const ScopedHostValue&) = delete;
};

