struct ValidationLabelReferenceScope {
  std::string reference;
  bool inserted = false;
  explicit ValidationLabelReferenceScope(std::string_view value)
      : reference(value) {
    inserted = !reference.empty() &&
        g_schema_label_definition_refs.insert(reference).second;
  }
  ~ValidationLabelReferenceScope() {
    if (inserted) g_schema_label_definition_refs.erase(reference);
  }
};

const char* known_error_default_message(std::string_view error_type,
                                        bool json_mode = false) {
  for (const auto& definition : kPydanticErrorTemplates) {
    if (error_type == definition.type)
      return json_mode ? definition.json_message : definition.message;
  }
  return nullptr;
}

