void cleanup_schema(void* pointer) {
  auto* state = static_cast<SchemaState*>(pointer);
  if (!state) return;
  state->package->host->value_release(state->schema);
  state->package->host->value_release(state->config);
  delete state;
}

void clear_schema(void* pointer) {
  auto* state = static_cast<SchemaState*>(pointer);
  if (!state) return;
  state->package->host->value_release(state->schema);
  state->package->host->value_release(state->config);
  state->schema = x3_value_invalid();
  state->config = x3_value_invalid();
}

void cleanup_wrapped(void* pointer) {
  auto* state = static_cast<WrappedValue*>(pointer);
  if (!state) return;
  state->package->host->value_release(state->first);
  state->package->host->value_release(state->second);
  delete state;
}

void clear_wrapped(void* pointer) {
  auto* state = static_cast<WrappedValue*>(pointer);
  if (!state) return;
  state->package->host->value_release(state->first);
  state->package->host->value_release(state->second);
  state->first = x3_value_invalid();
  state->second = x3_value_invalid();
}

void cleanup_url(void* pointer) {
  delete static_cast<UrlState*>(pointer);
}

void cleanup_tzinfo(void* pointer) {
  delete static_cast<TzInfoState*>(pointer);
}

void cleanup_validator_handler(void* pointer) {
  auto* state = static_cast<ValidatorHandlerState*>(pointer);
  if (!state) return;
  state->package->host->value_release(state->schema);
  state->package->host->value_release(state->definitions);
  state->package->host->value_release(state->self_instance);
  state->package->host->value_release(state->environment.context);
  state->package->host->value_release(state->environment.data);
  state->package->host->value_release(state->environment.config);
  delete state;
}

void cleanup_validator_iterator(void* pointer) {
  auto* state = static_cast<ValidatorIteratorState*>(pointer);
  if (state == nullptr) return;
  state->package->host->value_release(state->iterator);
  state->package->host->value_release(state->item_schema);
  state->package->host->value_release(state->definitions);
  state->package->host->value_release(state->original_input);
  state->package->host->value_release(state->environment.context);
  state->package->host->value_release(state->environment.data);
  state->package->host->value_release(state->environment.config);
  delete state;
}

void cleanup_serialization_iterator(void* pointer) {
  auto* state = static_cast<SerializationIteratorState*>(pointer);
  if (state == nullptr) return;
  state->package->host->value_release(state->iterator);
  state->package->host->value_release(state->item_schema);
  state->package->host->value_release(state->definitions);
  state->package->host->value_release(state->schema_include);
  state->package->host->value_release(state->schema_exclude);
  state->package->host->value_release(state->include);
  state->package->host->value_release(state->exclude);
  delete state;
}

void cleanup_package(void* pointer) {
  auto* state = static_cast<PackageState*>(pointer);
  if (!state) return;
  state->host->value_release(state->undefined);
  for (auto value : state->retained) state->host->value_release(value);
  delete state;
}

bool valid_argc(PackageState* state, X3CallContext* context, uint32_t argc,
                uint32_t minimum, uint32_t maximum, const char* name) {
  if (argc >= minimum && argc <= maximum) return true;
  const std::string message = std::string(name) + " received an invalid number of arguments";
  state->host->raise_class_error(context, "TypeError", message.c_str());
  return false;
}

X3Status raise_class_error(PackageState* package, X3CallContext* context,
                           const char* class_name, const char* message) {
  package->host->raise_class_error(context, class_name, message);
  return X3_STATUS_ERROR;
}

void define_method(X3NativeFunctionDef& def, const char* name, X3NativeFn callback,
                   PackageState* state, X3NativeKeywordFn keywords = nullptr) {
  def = {};
  def.size = sizeof(def);
  def.name = name;
  def.callback = callback;
  def.keyword_callback = keywords;
  def.user_data = state;
}

void add_function(PackageState* state, X3Module* module, const char* name,
                  X3NativeFn callback, X3NativeKeywordFn keywords = nullptr) {
  X3NativeFunctionDef def{};
  define_method(def, name, callback, state, keywords);
  state->host->module_add_function(module, &def);
}

bool add_property(PackageState* state, X3Runtime* runtime, X3Value klass,
                  const char* name, X3NativeFn getter) {
  X3Value property = x3_value_invalid();
  if (state->host->property_create(runtime, name, getter, nullptr, state, &property) != X3_STATUS_OK)
    return false;
  const bool ok = state->host->class_add_value(klass, name, property) == X3_STATUS_OK;
  state->host->value_release(property);
  return ok;
}

bool string_data(PackageState* state, X3Runtime* runtime, X3Value value,
                 std::string& output);
bool schema_type_name(PackageState* package, X3Runtime* runtime,
                      X3Value schema, std::string& type);
X3Status import_module(PackageState* package, X3Runtime* runtime,
                       const char* name, X3Value* result);
bool is_instance_of_class(PackageState* package, X3Runtime* runtime,
                          X3Value input, X3Value klass);

X3Status serialization_unexpected_init(
    X3CallContext* context, X3Runtime* runtime, void* user_data,
    const X3Value* args, uint32_t argc, X3Value*) {
  auto* package = static_cast<PackageState*>(user_data);
  if (!valid_argc(package, context, argc, 1, 2,
                  "PydanticSerializationUnexpectedValue()"))
    return X3_STATUS_ERROR;
  X3Value message = argc == 2
      ? args[1]
      : package->host->value_string(runtime, "Unexpected Value");
  X3Value values = package->host->value_list(runtime);
  X3Value tuple_class = x3_value_invalid();
  X3Value tuple = x3_value_invalid();
  const bool ready = values.tag != X3_TAG_INVALID &&
      package->host->list_append(runtime, values, message) == X3_STATUS_OK &&
      package->host->builtin_value(
          package->host, "tuple", &tuple_class) == X3_STATUS_OK &&
      package->host->call(runtime, tuple_class, &values, 1, &tuple) ==
          X3_STATUS_OK &&
      package->host->set_attr(runtime, args[0], "args", tuple) ==
          X3_STATUS_OK;
  if (tuple.tag != X3_TAG_INVALID) package->host->value_release(tuple);
  if (tuple_class.tag != X3_TAG_INVALID)
    package->host->value_release(tuple_class);
  if (values.tag != X3_TAG_INVALID) package->host->value_release(values);
  if (argc != 2) package->host->value_release(message);
  return ready ? X3_STATUS_OK : X3_STATUS_ERROR;
}

X3Status serialization_unexpected_str(
    X3CallContext* context, X3Runtime* runtime, void* user_data,
    const X3Value* args, uint32_t argc, X3Value* result) {
  auto* package = static_cast<PackageState*>(user_data);
  if (!valid_argc(package, context, argc, 1, 1,
                  "PydanticSerializationUnexpectedValue.__str__()"))
    return X3_STATUS_ERROR;
  X3Value values = x3_value_invalid();
  X3Value message = x3_value_invalid();
  X3Value str_function = x3_value_invalid();
  const bool ready = package->host->get_attr(
                         runtime, args[0], "args", &values) == X3_STATUS_OK &&
      package->host->get_item(
          runtime, values, x3_value_int64(0), &message) == X3_STATUS_OK &&
      package->host->builtin_value(
          package->host, "str", &str_function) == X3_STATUS_OK &&
      package->host->call(
          runtime, str_function, &message, 1, result) == X3_STATUS_OK;
  if (str_function.tag != X3_TAG_INVALID)
    package->host->value_release(str_function);
  if (message.tag != X3_TAG_INVALID) package->host->value_release(message);
  if (values.tag != X3_TAG_INVALID) package->host->value_release(values);
  return ready ? X3_STATUS_OK : X3_STATUS_ERROR;
}

X3Status serialization_unexpected_repr(
    X3CallContext* context, X3Runtime* runtime, void* user_data,
    const X3Value* args, uint32_t argc, X3Value* result) {
  auto* package = static_cast<PackageState*>(user_data);
  X3Value rendered = x3_value_invalid();
  std::string message;
  if (serialization_unexpected_str(
          context, runtime, user_data, args, argc, &rendered) != X3_STATUS_OK ||
      !string_data(package, runtime, rendered, message)) {
    if (rendered.tag != X3_TAG_INVALID)
      package->host->value_release(rendered);
    return X3_STATUS_ERROR;
  }
  package->host->value_release(rendered);
  const std::string text =
      "PydanticSerializationUnexpectedValue(" + message + ")";
  *result = package->host->value_string_utf8(
      runtime, text.data(), text.size());
  return X3_STATUS_OK;
}

X3Status schema_error_repr(X3CallContext* context, X3Runtime* runtime,
                           void* user_data, const X3Value* args,
                           uint32_t argc, X3Value* result) {
  auto* package = static_cast<PackageState*>(user_data);
  if (!valid_argc(package, context, argc, 1, 1, "SchemaError.__repr__"))
    return X3_STATUS_ERROR;
  X3Value str_function = x3_value_invalid();
  X3Value rendered = x3_value_invalid();
  std::string message;
  if (package->host->builtin_value(package->host, "str", &str_function) != X3_STATUS_OK ||
      package->host->call(runtime, str_function, args, 1, &rendered) != X3_STATUS_OK ||
      !string_data(package, runtime, rendered, message)) {
    if (rendered.tag != X3_TAG_INVALID) package->host->value_release(rendered);
    if (str_function.tag != X3_TAG_INVALID) package->host->value_release(str_function);
    return X3_STATUS_ERROR;
  }
  package->host->value_release(rendered);
  package->host->value_release(str_function);
  std::string escaped;
  escaped.reserve(message.size());
  for (const char ch : message) {
    if (ch == '\\' || ch == '"') escaped.push_back('\\');
    escaped.push_back(ch);
  }
  const std::string text = "SchemaError(\"" + escaped + "\")";
  *result = package->host->value_string(runtime, text.c_str());
  return X3_STATUS_OK;
}

X3Status pydantic_control_repr(X3CallContext* context, X3Runtime* runtime,
                               void* user_data, const X3Value*, uint32_t argc,
                               X3Value* result) {
  auto* package = static_cast<PackageState*>(user_data);
  if (!valid_argc(package, context, argc, 1, 1,
                  "Pydantic control exception repr()"))
    return X3_STATUS_ERROR;
  *result = package->host->value_string(runtime, "PydanticOmit()");
  return X3_STATUS_OK;
}

X3Status pydantic_use_default_repr(X3CallContext* context, X3Runtime* runtime,
                                   void* user_data, const X3Value*,
                                   uint32_t argc, X3Value* result) {
  auto* package = static_cast<PackageState*>(user_data);
  if (!valid_argc(package, context, argc, 1, 1,
                  "PydanticUseDefault repr()"))
    return X3_STATUS_ERROR;
  *result = package->host->value_string(runtime, "PydanticUseDefault()");
  return X3_STATUS_OK;
}

bool add_exception(PackageState* state, X3Module* module, const char* name,
                   X3Value base, X3Value* output) {
  X3NativeFunctionDef methods[3]{};
  uint32_t method_count = 0;
  if (std::string_view(name) == "SchemaError") {
    define_method(methods[0], "__repr__", schema_error_repr, state);
    method_count = 1;
  } else if (std::string_view(name) == "PydanticOmit" ||
             std::string_view(name) == "PydanticUseDefault") {
    const bool omit = std::string_view(name) == "PydanticOmit";
    define_method(methods[0], "__str__",
                  omit ? pydantic_control_repr : pydantic_use_default_repr,
                  state);
    define_method(methods[1], "__repr__",
                  omit ? pydantic_control_repr : pydantic_use_default_repr,
                  state);
    method_count = 2;
  } else if (std::string_view(name) ==
             "PydanticSerializationUnexpectedValue") {
    define_method(methods[0], "__init__", serialization_unexpected_init,
                  state);
    define_method(methods[1], "__str__", serialization_unexpected_str,
                  state);
    define_method(methods[2], "__repr__", serialization_unexpected_repr,
                  state);
    method_count = 3;
  }
  if (state->host->module_add_class(module, name, methods, method_count, output) != X3_STATUS_OK) return false;
  return state->host->class_set_base(*output, base) == X3_STATUS_OK;
}

bool dict_item(PackageState* state, X3Runtime* runtime, X3Value dict,
               const char* key, X3Value& value) {
  if (state->host->value_object_kind(dict) != X3_OBJECT_KIND_DICT) return false;
  uint64_t size = 0;
  if (state->host->len(runtime, dict, &size) != X3_STATUS_OK) return false;
  for (uint64_t index = 0; index < size; ++index) {
    X3Value candidate_key = x3_value_invalid();
    X3Value candidate_value = x3_value_invalid();
    if (state->host->dict_get_entry(runtime, dict, index, &candidate_key, &candidate_value) != X3_STATUS_OK)
      return false;
    const char* data = nullptr;
    uint64_t length = 0;
    const bool matches = state->host->value_string_data(runtime, candidate_key, &data, &length) == X3_STATUS_OK &&
        std::string_view(data, static_cast<size_t>(length)) == key;
    state->host->value_release(candidate_key);
    if (matches) {
      value = candidate_value;
      return true;
    }
    state->host->value_release(candidate_value);
  }
  return false;
}

bool string_data(PackageState* state, X3Runtime* runtime, X3Value value,
                 std::string& output) {
  const char* data = nullptr;
  uint64_t size = 0;
  if (state->host->value_string_data(runtime, value, &data, &size) != X3_STATUS_OK) return false;
  output.assign(data, static_cast<size_t>(size));
  return true;
}

bool render_with_builtin(PackageState* state, X3Runtime* runtime,
                         const char* name, X3Value value,
                         std::string& output) {
  X3Value callable = x3_value_invalid();
  X3Value rendered = x3_value_invalid();
  const bool ok =
      state->host->builtin_value(state->host, name, &callable) == X3_STATUS_OK &&
      state->host->call(runtime, callable, &value, 1, &rendered) == X3_STATUS_OK &&
      string_data(state, runtime, rendered, output);
  if (rendered.tag != X3_TAG_INVALID) state->host->value_release(rendered);
  if (callable.tag != X3_TAG_INVALID) state->host->value_release(callable);
  return ok;
}

bool ascii_digits_at(std::string_view text, size_t offset, size_t count) {
  if (offset + count > text.size()) return false;
  for (size_t index = offset; index < offset + count; ++index) {
    if (text[index] < '0' || text[index] > '9') return false;
  }
  return true;
}

int decimal_at(std::string_view text, size_t offset, size_t count) {
  int value = 0;
  for (size_t index = offset; index < offset + count; ++index)
    value = value * 10 + (text[index] - '0');
  return value;
}

std::string temporal_parse_reason(std::string_view kind,
                                  std::string_view text) {
  if (kind == "datetime" || kind == "date") {
    if (text.size() < 10) return "input is too short";
    if (!ascii_digits_at(text, 0, 4)) return "invalid character in year";
    const int year = decimal_at(text, 0, 4);
    if (year == 0) return "year 0 is out of range";
    if (text[4] != '-') return "invalid date separator, expected `-`";
    if (!ascii_digits_at(text, 5, 2)) return "invalid character in month";
    const int month = decimal_at(text, 5, 2);
    if (month < 1 || month > 12)
      return "month value is outside expected range of 1-12";
    if (text[7] != '-') return "invalid date separator, expected `-`";
    if (!ascii_digits_at(text, 8, 2)) return "invalid character in day";
    const int day = decimal_at(text, 8, 2);
    static constexpr int days_per_month[] =
        {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    const bool leap = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
    const int maximum_day = days_per_month[month] + (month == 2 && leap ? 1 : 0);
    if (day < 1 || day > maximum_day)
      return "day value is outside expected range";
    return "unexpected extra characters at the end of the input";
  }
  if (kind == "time") {
    if (text.size() < 5) return "input is too short";
    if (!ascii_digits_at(text, 0, 2)) return "invalid character in hour";
    const int hour = decimal_at(text, 0, 2);
    if (hour > 23) return "hour value is outside expected range of 0-23";
    if (text[2] != ':') return "invalid time separator, expected `:`";
    if (!ascii_digits_at(text, 3, 2)) return "invalid character in minute";
    const int minute = decimal_at(text, 3, 2);
    if (minute > 59) return "minute value is outside expected range of 0-59";
    return "unexpected extra characters at the end of the input";
  }
  return "invalid input";
}

void lowercase_ascii(std::string& value) {
  for (char& character : value) {
    const auto byte = static_cast<unsigned char>(character);
    if (byte >= 'A' && byte <= 'Z') character = static_cast<char>(byte + ('a' - 'A'));
  }
}

int64_t scheme_default_port(const std::string& scheme) {
  if (scheme == "http" || scheme == "ws") return 80;
  if (scheme == "https" || scheme == "wss") return 443;
  if (scheme == "ftp") return 21;
  return 0;
}

bool parse_ipv4_number(std::string_view input, uint64_t& value) {
  if (input.empty()) return false;
  unsigned base = 10;
  size_t cursor = 0;
  if (input.size() >= 2 && input[0] == '0' &&
      (input[1] == 'x' || input[1] == 'X')) {
    base = 16;
    cursor = 2;
  } else if (input.size() >= 2 && input[0] == '0') {
    base = 8;
    cursor = 1;
  }
  if (cursor == input.size()) {
    value = 0;
    return true;
  }
  value = 0;
  for (; cursor < input.size(); ++cursor) {
    const unsigned char byte = static_cast<unsigned char>(input[cursor]);
    unsigned digit = 0;
    if (byte >= '0' && byte <= '9') digit = byte - '0';
    else if (byte >= 'a' && byte <= 'f') digit = byte - 'a' + 10;
    else if (byte >= 'A' && byte <= 'F') digit = byte - 'A' + 10;
    else return false;
    if (digit >= base || value > (UINT32_MAX - digit) / base) return false;
    value = value * base + digit;
  }
  return true;
}

bool host_ends_in_number(std::string_view host) {
  if (!host.empty() && host.back() == '.') host.remove_suffix(1);
  const size_t dot = host.rfind('.');
  const std::string_view label =
      dot == std::string_view::npos ? host : host.substr(dot + 1);
  uint64_t ignored = 0;
  return parse_ipv4_number(label, ignored);
}

bool normalize_ipv4_host(std::string_view input, std::string& output) {
  std::vector<uint64_t> parts;
  size_t start = 0;
  for (size_t index = 0; index <= input.size(); ++index) {
    if (index != input.size() && input[index] != '.') continue;
    const std::string_view part = input.substr(start, index - start);
    if (part.empty()) {
      if (index == input.size() && !parts.empty()) break;
      return false;
    }
    uint64_t number = 0;
    if (!parse_ipv4_number(part, number)) return false;
    parts.push_back(number);
    if (parts.size() > 4) return false;
    start = index + 1;
  }
  if (parts.empty()) return false;
  for (size_t index = 0; index + 1 < parts.size(); ++index) {
    if (parts[index] > 255) return false;
  }
  uint64_t maximum_last = 1;
  for (size_t index = parts.size(); index < 5; ++index)
    maximum_last *= 256;
  if (parts.back() >= maximum_last) return false;
  uint64_t address = parts.back();
  for (size_t index = 0; index + 1 < parts.size(); ++index) {
    unsigned shift = static_cast<unsigned>(8 * (3 - index));
    address += parts[index] << shift;
  }
  output = std::to_string((address >> 24) & 255) + "." +
      std::to_string((address >> 16) & 255) + "." +
      std::to_string((address >> 8) & 255) + "." +
      std::to_string(address & 255);
  return true;
}

bool parse_ipv6_piece(std::string_view piece, std::vector<uint16_t>& groups) {
  if (piece.empty()) return true;
  size_t start = 0;
  while (start <= piece.size()) {
    const size_t colon = piece.find(':', start);
    const size_t end = colon == std::string_view::npos ? piece.size() : colon;
    const std::string_view token = piece.substr(start, end - start);
    if (token.empty()) return false;
    if (token.find('.') != std::string_view::npos) {
      if (end != piece.size()) return false;
      std::array<unsigned, 4> bytes{};
      size_t byte_start = 0;
      for (size_t index = 0; index < bytes.size(); ++index) {
        const size_t dot = token.find('.', byte_start);
        const size_t byte_end = dot == std::string_view::npos ? token.size() : dot;
        if ((index < 3 && dot == std::string_view::npos) ||
            (index == 3 && dot != std::string_view::npos) ||
            byte_end == byte_start)
          return false;
        unsigned value = 0;
        const auto parsed = std::from_chars(
            token.data() + byte_start, token.data() + byte_end, value);
        if (parsed.ec != std::errc{} ||
            parsed.ptr != token.data() + byte_end || value > 255)
          return false;
        bytes[index] = value;
        byte_start = byte_end + 1;
      }
      groups.push_back(static_cast<uint16_t>((bytes[0] << 8) | bytes[1]));
      groups.push_back(static_cast<uint16_t>((bytes[2] << 8) | bytes[3]));
    } else {
      if (token.size() > 4) return false;
      unsigned value = 0;
      const auto parsed = std::from_chars(
          token.data(), token.data() + token.size(), value, 16);
      if (parsed.ec != std::errc{} ||
          parsed.ptr != token.data() + token.size() || value > 0xffff)
        return false;
      groups.push_back(static_cast<uint16_t>(value));
    }
    if (colon == std::string_view::npos) break;
    start = colon + 1;
  }
  return true;
}

bool normalize_ipv6_host(std::string_view input, std::string& output) {
  const size_t compression = input.find("::");
  if (compression != std::string_view::npos &&
      input.find("::", compression + 2) != std::string_view::npos)
    return false;
  std::vector<uint16_t> left;
  std::vector<uint16_t> right;
  if (compression == std::string_view::npos) {
    if (!parse_ipv6_piece(input, left) || left.size() != 8) return false;
  } else {
    if (!parse_ipv6_piece(input.substr(0, compression), left) ||
        !parse_ipv6_piece(input.substr(compression + 2), right) ||
        left.size() + right.size() >= 8)
      return false;
    left.resize(8 - right.size(), 0);
    left.insert(left.end(), right.begin(), right.end());
  }

  size_t best_start = 8;
  size_t best_length = 0;
  for (size_t index = 0; index < 8;) {
    if (left[index] != 0) {
      ++index;
      continue;
    }
    size_t end = index;
    while (end < 8 && left[end] == 0) ++end;
    if (end - index > best_length) {
      best_start = index;
      best_length = end - index;
    }
    index = end;
  }
  if (best_length < 2) best_start = 8;

  std::ostringstream stream;
  stream << '[';
  bool wrote_group = false;
  bool after_compression = false;
  for (size_t index = 0; index < 8;) {
    if (index == best_start) {
      stream << "::";
      index += best_length;
      after_compression = true;
      continue;
    }
    if (wrote_group && !after_compression) stream << ':';
    stream << std::hex << std::nouppercase << left[index];
    wrote_group = true;
    after_compression = false;
    ++index;
  }
  stream << ']';
  output = stream.str();
  return true;
}

int ascii_hex_value(unsigned char byte) {
  if (byte >= '0' && byte <= '9') return byte - '0';
  if (byte >= 'a' && byte <= 'f') return byte - 'a' + 10;
  if (byte >= 'A' && byte <= 'F') return byte - 'A' + 10;
  return -1;
}

bool decode_special_domain(std::string_view input, std::string& output) {
  output.clear();
  for (size_t index = 0; index < input.size(); ++index) {
    unsigned char byte = static_cast<unsigned char>(input[index]);
    if (byte == '%') {
      if (index + 2 >= input.size()) return false;
      const int high = ascii_hex_value(static_cast<unsigned char>(input[index + 1]));
      const int low = ascii_hex_value(static_cast<unsigned char>(input[index + 2]));
      if (high < 0 || low < 0) return false;
      byte = static_cast<unsigned char>((high << 4) | low);
      index += 2;
    }
    switch (byte) {
      case 0x00:
      case 0x09:
      case 0x0a:
      case 0x0d:
      case 0x20:
      case '#':
      case '/':
      case ':':
      case '<':
      case '>':
      case '?':
      case '@':
      case '[':
      case '\\':
      case ']':
      case '^':
      case '|':
        return false;
      default:
        output.push_back(static_cast<char>(byte));
        break;
    }
  }
  return true;
}

std::string percent_encode_non_ascii(std::string_view input) {
  static constexpr char hexadecimal[] = "0123456789ABCDEF";
  std::string output;
  output.reserve(input.size());
  for (unsigned char byte : input) {
    if (byte < 0x80) {
      output.push_back(static_cast<char>(byte));
    } else {
      output.push_back('%');
      output.push_back(hexadecimal[byte >> 4]);
      output.push_back(hexadecimal[byte & 0x0f]);
    }
  }
  return output;
}

std::string percent_encode_userinfo(std::string_view input) {
  static constexpr char hexadecimal[] = "0123456789ABCDEF";
  std::string output;
  output.reserve(input.size());
  for (size_t index = 0; index < input.size(); ++index) {
    const unsigned char byte = static_cast<unsigned char>(input[index]);
    const bool valid_escape = byte == '%' && index + 2 < input.size() &&
        ascii_hex_value(static_cast<unsigned char>(input[index + 1])) >= 0 &&
        ascii_hex_value(static_cast<unsigned char>(input[index + 2])) >= 0;
    const bool encode = byte >= 0x80 || byte <= 0x20 || byte == 0x7f ||
        std::string_view("\"#<>?`{}/:;=@[\\]^|").find(
            static_cast<char>(byte)) != std::string_view::npos;
    if (!encode || valid_escape) {
      output.push_back(static_cast<char>(byte));
    } else {
      output.push_back('%');
      output.push_back(hexadecimal[byte >> 4]);
      output.push_back(hexadecimal[byte & 0x0f]);
    }
  }
  return output;
}

std::string percent_encode_url_component(std::string_view input) {
  static constexpr char hexadecimal[] = "0123456789ABCDEF";
  std::string output;
  output.reserve(input.size());
  for (unsigned char byte : input) {
    const bool encode = byte >= 0x80 || byte <= 0x20 || byte == 0x7f ||
        std::string_view("\"<>`{}").find(static_cast<char>(byte)) !=
            std::string_view::npos;
    if (!encode) {
      output.push_back(static_cast<char>(byte));
    } else {
      output.push_back('%');
      output.push_back(hexadecimal[byte >> 4]);
      output.push_back(hexadecimal[byte & 0x0f]);
    }
  }
  return output;
}

bool parse_url_host(std::string_view input, UrlHost& output, std::string& error) {
  std::string_view host_port = input;
  const size_t at = input.rfind('@');
  if (at != std::string_view::npos) {
    const std::string_view user_info = input.substr(0, at);
    host_port = input.substr(at + 1);
    const size_t colon = user_info.find(':');
    output.username = percent_encode_userinfo(user_info.substr(0, colon));
    output.has_username = true;
    if (colon != std::string_view::npos && colon + 1 < user_info.size()) {
      output.password = percent_encode_userinfo(user_info.substr(colon + 1));
      output.has_password = true;
    }
  }
  if (host_port.empty()) {
    error = "empty host";
    return false;
  }
  std::string_view port_text;
  if (host_port.front() == '[') {
    const size_t close = host_port.find(']');
    if (close == std::string_view::npos) {
      error = "invalid IPv6 address";
      return false;
    }
    output.host.assign(host_port.substr(0, close + 1));
    if (close + 1 < host_port.size()) {
      if (host_port[close + 1] != ':') {
        error = "unexpected text after IPv6 address";
        return false;
      }
      port_text = host_port.substr(close + 2);
    }
  } else {
    const size_t colon = host_port.rfind(':');
    if (colon != std::string_view::npos) {
      if (host_port.find(':') != colon) {
        error = "IPv6 addresses must be enclosed in brackets";
        return false;
      }
      output.host.assign(host_port.substr(0, colon));
      port_text = host_port.substr(colon + 1);
    } else {
      output.host.assign(host_port);
    }
  }
  if (output.host.empty()) {
    error = "empty host";
    return false;
  }
  output.unicode_host = output.host;
  if (!port_text.empty()) {
    int64_t port = 0;
    const auto parsed = std::from_chars(
        port_text.data(), port_text.data() + port_text.size(), port);
    if (parsed.ec != std::errc{} || parsed.ptr != port_text.data() + port_text.size() ||
        port < 0 || port > 65535) {
      error = "invalid port number";
      return false;
    }
    output.port = port;
    output.has_port = true;
  } else if (!port_text.empty() || (!host_port.empty() && host_port.back() == ':')) {
    error = "invalid port number";
    return false;
  }
  return true;
}

void rebuild_url(UrlState& url) {
  std::string output = url.scheme + ":";
  if (url.has_authority) {
    output += "//";
    for (size_t index = 0; index < url.hosts.size(); ++index) {
      if (index) output.push_back(',');
      const auto& host = url.hosts[index];
      if (host.has_username) {
        output += host.username;
        if (host.has_password) output += ":" + host.password;
        output.push_back('@');
      }
      output += host.host;
      const int64_t default_port = scheme_default_port(url.scheme);
      if (host.has_port && (default_port == 0 || host.port != default_port))
        output += ":" + std::to_string(host.port);
    }
  }
  output += url.path;
  if (url.has_query) output += "?" + url.query;
  if (url.has_fragment) output += "#" + url.fragment;
  url.serialized = std::move(output);
}

bool parse_url_text(std::string text, bool multi, UrlState& output,
                    std::string& error, bool preserve_empty_path = false,
                    bool allow_empty_host = false) {
  text.erase(std::remove_if(text.begin(), text.end(), [](unsigned char byte) {
               return byte == '\t' || byte == '\n' || byte == '\r';
             }),
             text.end());
  while (!text.empty() && std::isspace(static_cast<unsigned char>(text.front())))
    text.erase(text.begin());
  while (!text.empty() && std::isspace(static_cast<unsigned char>(text.back())))
    text.pop_back();
  if (text.empty()) {
    error = "input is empty";
    return false;
  }
  for (unsigned char byte : text) {
    if (byte < 0x20 || byte == 0x7f) {
      error = "control character in URL";
      return false;
    }
  }
  const size_t scheme_end = text.find(':');
  const size_t first_separator = text.find_first_of("/?#");
  if (scheme_end == std::string::npos || scheme_end == 0 ||
      (first_separator != std::string::npos && scheme_end > first_separator) ||
      !std::isalpha(static_cast<unsigned char>(text.front()))) {
    error = "relative URL without a base";
    return false;
  }
  for (size_t index = 1; index < scheme_end; ++index) {
    const unsigned char byte = static_cast<unsigned char>(text[index]);
    if (!std::isalnum(byte) && byte != '+' && byte != '-' && byte != '.') {
      error = "relative URL without a base";
      return false;
    }
  }
  output = {};
  output.multi = multi;
  output.scheme = text.substr(0, scheme_end);
  lowercase_ascii(output.scheme);
  size_t cursor = scheme_end + 1;
  const bool network_special =
      output.scheme == "http" || output.scheme == "https" ||
      output.scheme == "ws" || output.scheme == "wss" ||
      output.scheme == "ftp";
  if (output.scheme == "file") {
    for (size_t index = cursor; index < text.size(); ++index) {
      if (text[index] == '\\') text[index] = '/';
    }
  }
  bool parse_authority = false;
  if (network_special) {
    for (size_t index = cursor; index < text.size(); ++index) {
      if (text[index] == '\\') text[index] = '/';
    }
    while (cursor < text.size() && text[cursor] == '/') ++cursor;
    output.has_authority = true;
    parse_authority = true;
  } else if (text.compare(cursor, 2, "//") == 0) {
    output.has_authority = true;
    cursor += 2;
    parse_authority = true;
  }
  if (parse_authority) {
    const size_t authority_end = text.find_first_of("/?#", cursor);
    const size_t end = authority_end == std::string::npos ? text.size() : authority_end;
    const std::string_view authority(text.data() + cursor, end - cursor);
    if (authority.empty() && output.scheme != "file" &&
        (!allow_empty_host || network_special)) {
      error = "empty host";
      return false;
    }
    if (!authority.empty() && output.scheme == "file" &&
        authority.front() == ':') {
      error = "invalid international domain name";
      return false;
    }
    if (!authority.empty()) {
      size_t start = 0;
      int bracket_depth = 0;
      for (size_t index = 0; index <= authority.size(); ++index) {
        if (index < authority.size() && authority[index] == '[') ++bracket_depth;
        if (index < authority.size() && authority[index] == ']') --bracket_depth;
        const bool boundary = index == authority.size() ||
            (multi && authority[index] == ',' && bracket_depth == 0);
        if (!boundary) continue;
        UrlHost host;
        if (!parse_url_host(authority.substr(start, index - start), host, error)) return false;
        output.hosts.push_back(std::move(host));
        start = index + 1;
      }
    }
    cursor = end;
  }
  const size_t query_start = text.find('?', cursor);
  const size_t fragment_start = text.find('#', cursor);
  size_t path_end = text.size();
  if (query_start != std::string::npos) path_end = std::min(path_end, query_start);
  if (fragment_start != std::string::npos) path_end = std::min(path_end, fragment_start);
  output.path = percent_encode_url_component(
      std::string_view(text).substr(cursor, path_end - cursor));
  if (query_start != std::string::npos &&
      (fragment_start == std::string::npos || query_start < fragment_start)) {
    output.has_query = true;
    const size_t end = fragment_start == std::string::npos ? text.size() : fragment_start;
    output.query = percent_encode_url_component(
        std::string_view(text).substr(query_start + 1,
                                      end - query_start - 1));
  }
  if (fragment_start != std::string::npos) {
    output.has_fragment = true;
    output.fragment = percent_encode_url_component(
        std::string_view(text).substr(fragment_start + 1));
  }
  if (!multi && output.hosts.size() > 1) {
    error = "multiple hosts are not permitted";
    return false;
  }
  if (multi && !output.has_authority) {
    error = "empty host";
    return false;
  }
  if (output.has_authority && output.path.empty() &&
      (output.scheme == "http" || output.scheme == "https" ||
       output.scheme == "ws" || output.scheme == "wss" || output.scheme == "ftp") &&
      !preserve_empty_path)
    output.path = "/";
  rebuild_url(output);
  return true;
}

UrlState* url_state(PackageState* package, X3CallContext* context, X3Value value,
                    bool multi) {
  auto* state = static_cast<UrlState*>(package->host->instance_get_native_data(
      value, multi ? kMultiHostUrlType : kUrlType));
  if (state == nullptr)
    package->host->raise_class_error(context, "TypeError", "invalid URL instance");
  return state;
}

bool dict_find_string(PackageState* state, X3Runtime* runtime, X3Value dict,
                      const std::string& wanted, X3Value& value) {
  if (state->host->value_object_kind(dict) != X3_OBJECT_KIND_DICT) return false;
  uint64_t size = 0;
  if (state->host->len(runtime, dict, &size) != X3_STATUS_OK) return false;
  for (uint64_t index = 0; index < size; ++index) {
    X3Value key = x3_value_invalid();
    X3Value candidate = x3_value_invalid();
    if (state->host->dict_get_entry(runtime, dict, index, &key, &candidate) != X3_STATUS_OK) return false;
    std::string key_text;
    const bool matches = string_data(state, runtime, key, key_text) && key_text == wanted;
    state->host->value_release(key);
    if (matches) {
      value = candidate;
      return true;
    }
    state->host->value_release(candidate);
  }
  return false;
}

bool is_mapping_protocol_instance(PackageState* package, X3Runtime* runtime,
                                  X3Value value) {
  X3Value module = x3_value_invalid();
  X3Value mapping_class = x3_value_invalid();
  const bool matches =
      import_module(package, runtime, "_collections_abc", &module) ==
          X3_STATUS_OK &&
      package->host->get_attr(runtime, module, "Mapping", &mapping_class) ==
          X3_STATUS_OK &&
      is_instance_of_class(package, runtime, value, mapping_class);
  if (mapping_class.tag != X3_TAG_INVALID)
    package->host->value_release(mapping_class);
  if (module.tag != X3_TAG_INVALID) package->host->value_release(module);
  return matches;
}

X3Status find_model_field_input(PackageState* package, X3Runtime* runtime,
                                X3Value input, const std::string& name,
                                bool from_attributes, bool* present,
                                X3Value* value) {
  *present = false;
  *value = x3_value_invalid();
  if (package->host->value_object_kind(input) == X3_OBJECT_KIND_DICT) {
    *present = dict_find_string(package, runtime, input, name, *value);
    return X3_STATUS_OK;
  }
  if (!from_attributes) return X3_STATUS_OK;
  if (is_mapping_protocol_instance(package, runtime, input)) {
    X3Value get_method = x3_value_invalid();
    X3Value name_value = package->host->value_string_utf8(
        runtime, name.data(), name.size());
    X3Value arguments[] = {name_value, package->undefined};
    const auto status =
        package->host->get_attr(runtime, input, "get", &get_method) ==
                X3_STATUS_OK
            ? package->host->call(runtime, get_method, arguments, 2, value)
            : X3_STATUS_ERROR;
    if (get_method.tag != X3_TAG_INVALID)
      package->host->value_release(get_method);
    package->host->value_release(name_value);
    if (status != X3_STATUS_OK) return status;
    if (value->tag == package->undefined.tag && value->tag == X3_TAG_OBJECT &&
        value->as.obj == package->undefined.as.obj) {
      package->host->value_release(*value);
      *value = x3_value_invalid();
      return X3_STATUS_OK;
    }
    *present = true;
    return X3_STATUS_OK;
  }
  if (package->host->value_object_kind(input) == X3_OBJECT_KIND_TUPLE) {
    uint64_t count = 0;
    X3Value object = x3_value_invalid();
    X3Value overrides = x3_value_invalid();
    if (package->host->len(runtime, input, &count) == X3_STATUS_OK &&
        count == 2 &&
        package->host->get_item(runtime, input, x3_value_int64(0), &object) ==
            X3_STATUS_OK &&
        package->host->get_item(
            runtime, input, x3_value_int64(1), &overrides) == X3_STATUS_OK &&
        package->host->value_object_kind(overrides) == X3_OBJECT_KIND_DICT) {
      *present = dict_find_string(package, runtime, overrides, name, *value);
      if (!*present) {
        const auto status = find_model_field_input(
            package, runtime, object, name, true, present, value);
        package->host->value_release(object);
        package->host->value_release(overrides);
        return status;
      }
      package->host->value_release(object);
      package->host->value_release(overrides);
      return X3_STATUS_OK;
    }
    if (object.tag != X3_TAG_INVALID) package->host->value_release(object);
    if (overrides.tag != X3_TAG_INVALID)
      package->host->value_release(overrides);
    return X3_STATUS_OK;
  }

  X3Value getattr_function = x3_value_invalid();
  X3Value name_value = package->host->value_string_utf8(
      runtime, name.data(), name.size());
  if (name_value.tag == X3_TAG_INVALID ||
      package->host->builtin_value(package->host, "getattr", &getattr_function) !=
          X3_STATUS_OK) {
    if (name_value.tag != X3_TAG_INVALID)
      package->host->value_release(name_value);
    return X3_STATUS_ERROR;
  }
  X3Value arguments[] = {input, name_value, package->undefined};
  const auto status = package->host->call(
      runtime, getattr_function, arguments, 3, value);
  package->host->value_release(getattr_function);
  package->host->value_release(name_value);
  if (status != X3_STATUS_OK) return status;
  if (value->tag == package->undefined.tag && value->tag == X3_TAG_OBJECT &&
      value->as.obj == package->undefined.as.obj) {
    package->host->value_release(*value);
    *value = x3_value_invalid();
    return X3_STATUS_OK;
  }
  *present = true;
  return X3_STATUS_OK;
}

X3Status find_alias_path_input(
    PackageState* package, X3Runtime* runtime, X3Value input, X3Value alias,
    bool* present, X3Value* value, std::vector<std::string>* path,
    bool from_attributes = false) {
  *present = false;
  *value = x3_value_invalid();
  path->clear();
  std::string direct_name;
  if (string_data(package, runtime, alias, direct_name)) {
    *present = dict_find_string(package, runtime, input, direct_name, *value);
    if (*present) path->push_back(direct_name);
    return X3_STATUS_OK;
  }
  const auto alias_kind = package->host->value_object_kind(alias);
  if (alias_kind != X3_OBJECT_KIND_LIST && alias_kind != X3_OBJECT_KIND_TUPLE)
    return X3_STATUS_OK;
  uint64_t path_length = 0;
  if (package->host->len(runtime, alias, &path_length) != X3_STATUS_OK)
    return X3_STATUS_ERROR;
  for (uint64_t index = 0; index < path_length; ++index) {
    X3Value component = x3_value_invalid();
    if (package->host->get_item(
            runtime, alias, x3_value_int64(static_cast<int64_t>(index)),
            &component) != X3_STATUS_OK)
      return X3_STATUS_ERROR;
    std::string name;
    if (string_data(package, runtime, component, name)) {
      path->push_back(name);
    } else if (component.tag == X3_TAG_INT64) {
      path->push_back(std::string(kLocationIndexPrefix) +
                      std::to_string(component.as.i64));
    }
    package->host->value_release(component);
  }
  X3Value current = input;
  package->host->value_retain(current);
  for (uint64_t index = 0; index < path_length; ++index) {
    X3Value component = x3_value_invalid();
    if (package->host->get_item(
            runtime, alias, x3_value_int64(static_cast<int64_t>(index)),
            &component) != X3_STATUS_OK) {
      package->host->value_release(current);
      return X3_STATUS_ERROR;
    }
    X3Value next = x3_value_invalid();
    std::string name;
    bool found = false;
    if (string_data(package, runtime, component, name)) {
      if (package->host->value_object_kind(current) == X3_OBJECT_KIND_DICT) {
        found = dict_find_string(package, runtime, current, name, next);
      } else if (from_attributes) {
        bool attribute_present = false;
        const auto attribute_status = find_model_field_input(
            package, runtime, current, name, true, &attribute_present, &next);
        if (attribute_status != X3_STATUS_OK) {
          package->host->value_release(component);
          package->host->value_release(current);
          if (next.tag != X3_TAG_INVALID)
            package->host->value_release(next);
          return attribute_status;
        }
        found = attribute_present;
      }
    } else if (component.tag == X3_TAG_INT64) {
      const auto current_kind = package->host->value_object_kind(current);
      uint64_t current_length = 0;
      if (current_kind == X3_OBJECT_KIND_LIST ||
          current_kind == X3_OBJECT_KIND_TUPLE) {
        found = package->host->len(runtime, current, &current_length) ==
            X3_STATUS_OK;
        int64_t normalized = component.as.i64;
        if (found && normalized < 0)
          normalized += static_cast<int64_t>(current_length);
        found = found && normalized >= 0 &&
            static_cast<uint64_t>(normalized) < current_length;
        if (found) {
          X3Value normalized_index = x3_value_int64(normalized);
          found = package->host->get_item(
                      runtime, current, normalized_index, &next) ==
              X3_STATUS_OK;
        }
      } else if (current_kind == X3_OBJECT_KIND_DICT) {
        uint64_t dict_count = 0;
        if (package->host->len(runtime, current, &dict_count) == X3_STATUS_OK) {
          for (uint64_t dict_index = 0; dict_index < dict_count; ++dict_index) {
            X3Value candidate_key = x3_value_invalid();
            X3Value candidate_value = x3_value_invalid();
            if (package->host->dict_get_entry(
                    runtime, current, dict_index, &candidate_key,
                    &candidate_value) != X3_STATUS_OK)
              break;
            const bool matches = candidate_key.tag == X3_TAG_INT64 &&
                candidate_key.as.i64 == component.as.i64;
            package->host->value_release(candidate_key);
            if (matches) {
              next = candidate_value;
              found = true;
              break;
            }
            package->host->value_release(candidate_value);
          }
        }
      }
    }
    package->host->value_release(component);
    package->host->value_release(current);
    if (!found) {
      if (next.tag != X3_TAG_INVALID) package->host->value_release(next);
      return X3_STATUS_OK;
    }
    current = next;
  }
  *present = true;
  *value = current;
  return X3_STATUS_OK;
}

X3Status find_validation_alias_input(
    PackageState* package, X3Runtime* runtime, X3Value input, X3Value alias,
    bool from_attributes, bool* present, X3Value* value,
    std::vector<std::string>* path) {
  *present = false;
  *value = x3_value_invalid();
  path->clear();
  std::string direct_name;
  if (string_data(package, runtime, alias, direct_name)) {
    path->push_back(direct_name);
    return find_model_field_input(
        package, runtime, input, direct_name, from_attributes, present, value);
  }
  const auto alias_kind = package->host->value_object_kind(alias);
  if (alias_kind != X3_OBJECT_KIND_LIST &&
      alias_kind != X3_OBJECT_KIND_TUPLE)
    return X3_STATUS_OK;
  uint64_t count = 0;
  if (package->host->len(runtime, alias, &count) != X3_STATUS_OK || count == 0)
    return X3_STATUS_OK;
  X3Value first = x3_value_invalid();
  if (package->host->get_item(runtime, alias, x3_value_int64(0), &first) !=
      X3_STATUS_OK)
    return X3_STATUS_ERROR;
  const auto first_kind = package->host->value_object_kind(first);
  const bool choices = first_kind == X3_OBJECT_KIND_LIST ||
      first_kind == X3_OBJECT_KIND_TUPLE;
  package->host->value_release(first);
  if (!choices)
    return find_alias_path_input(
        package, runtime, input, alias, present, value, path,
        from_attributes);
  std::vector<std::string> first_path;
  for (uint64_t index = 0; index < count; ++index) {
    X3Value choice = x3_value_invalid();
    if (package->host->get_item(
            runtime, alias, x3_value_int64(static_cast<int64_t>(index)),
            &choice) != X3_STATUS_OK)
      return X3_STATUS_ERROR;
    const auto status = find_alias_path_input(
        package, runtime, input, choice, present, value, path,
        from_attributes);
    package->host->value_release(choice);
    if (status != X3_STATUS_OK || *present) return status;
    if (index == 0) first_path = *path;
  }
  *path = std::move(first_path);
  return X3_STATUS_OK;
}

X3Status model_field_should_serialize(PackageState* package,
                                      X3Runtime* runtime, X3Value input,
                                      X3Value key, bool exclude_unset,
                                      bool* include) {
  *include = true;
  if (!exclude_unset ||
      package->host->value_object_kind(input) == X3_OBJECT_KIND_DICT)
    return X3_STATUS_OK;

  X3Value getattr_function = x3_value_invalid();
  X3Value name = package->host->value_string(runtime,
                                              "__pydantic_fields_set__");
  X3Value fields_set = x3_value_invalid();
  if (package->host->builtin_value(package->host, "getattr",
                                   &getattr_function) != X3_STATUS_OK) {
    package->host->value_release(name);
    return X3_STATUS_ERROR;
  }
  X3Value arguments[] = {input, name, package->undefined};
  const auto getattr_status = package->host->call(
      runtime, getattr_function, arguments, 3, &fields_set);
  package->host->value_release(getattr_function);
  package->host->value_release(name);
  if (getattr_status != X3_STATUS_OK) return getattr_status;
  if (fields_set.tag == package->undefined.tag &&
      fields_set.tag == X3_TAG_OBJECT &&
      fields_set.as.obj == package->undefined.as.obj) {
    package->host->value_release(fields_set);
    return X3_STATUS_OK;
  }

  X3Value contains = x3_value_invalid();
  X3Value contained = x3_value_invalid();
  if (package->host->get_attr(runtime, fields_set, "__contains__", &contains) !=
          X3_STATUS_OK ||
      package->host->call(runtime, contains, &key, 1, &contained) !=
          X3_STATUS_OK) {
    if (contains.tag != X3_TAG_INVALID)
      package->host->value_release(contains);
    if (contained.tag != X3_TAG_INVALID)
      package->host->value_release(contained);
    package->host->value_release(fields_set);
    return X3_STATUS_ERROR;
  }
  *include = contained.tag == X3_TAG_BOOL && contained.as.b;
  package->host->value_release(contained);
  package->host->value_release(contains);
  package->host->value_release(fields_set);
  return X3_STATUS_OK;
}

bool same_object(X3Value left, X3Value right);

X3Status model_field_value_is_default(PackageState* package,
                                      X3Runtime* runtime,
                                      X3Value field_schema, X3Value value,
                                      bool* equal) {
  *equal = false;
  X3Value schema = x3_value_invalid();
  X3Value type_value = x3_value_invalid();
  std::string type;
  if (!dict_item(package, runtime, field_schema, "schema", schema))
    return X3_STATUS_OK;
  const bool is_default =
      dict_item(package, runtime, schema, "type", type_value) &&
      string_data(package, runtime, type_value, type) && type == "default";
  if (type_value.tag != X3_TAG_INVALID)
    package->host->value_release(type_value);
  if (!is_default) {
    package->host->value_release(schema);
    return X3_STATUS_OK;
  }

  X3Value default_value = x3_value_invalid();
  bool owns_default = false;
  if (dict_item(package, runtime, schema, "default", default_value)) {
    owns_default = true;
  } else {
    X3Value factory = x3_value_invalid();
    if (dict_item(package, runtime, schema, "default_factory", factory)) {
      const auto status =
          package->host->call(runtime, factory, nullptr, 0, &default_value);
      package->host->value_release(factory);
      if (status != X3_STATUS_OK) {
        package->host->value_release(schema);
        return status;
      }
      owns_default = true;
    }
  }
  package->host->value_release(schema);
  if (!owns_default) return X3_STATUS_OK;
  int32_t comparison = 0;
  const auto status = package->host->value_compare_op(
      runtime, X3_VALUE_COMPARE_EQ, value, default_value, &comparison);
  package->host->value_release(default_value);
  if (status == X3_STATUS_OK) *equal = comparison != 0;
  return status;
}

X3Status model_field_selector(PackageState* package, X3Runtime* runtime,
                              X3Value selector, X3Value key,
                              bool exclude_selector, bool* selected,
                              X3Value* child_selector) {
  *selected = !exclude_selector;
  *child_selector = x3_value_none();
  if (selector.tag == X3_TAG_NONE || selector.tag == X3_TAG_INVALID) {
    *selected = true;
    return X3_STATUS_OK;
  }

  X3Value rule = x3_value_invalid();
  bool contains = false;
  if (package->host->value_object_kind(selector) == X3_OBJECT_KIND_DICT) {
    std::string name;
    if (!string_data(package, runtime, key, name)) return X3_STATUS_ERROR;
    contains = dict_find_string(package, runtime, selector, name, rule);
  } else {
    X3Value contains_method = x3_value_invalid();
    X3Value answer = x3_value_invalid();
    if (package->host->get_attr(runtime, selector, "__contains__",
                                &contains_method) != X3_STATUS_OK ||
        package->host->call(runtime, contains_method, &key, 1, &answer) !=
            X3_STATUS_OK) {
      if (contains_method.tag != X3_TAG_INVALID)
        package->host->value_release(contains_method);
      if (answer.tag != X3_TAG_INVALID) package->host->value_release(answer);
      return X3_STATUS_ERROR;
    }
    contains = answer.tag == X3_TAG_BOOL && answer.as.b;
    package->host->value_release(answer);
    package->host->value_release(contains_method);
  }

  if (!contains) {
    *selected = exclude_selector;
    return X3_STATUS_OK;
  }
  *selected = true;
  if (rule.tag == X3_TAG_INVALID) {
    *selected = !exclude_selector;
    return X3_STATUS_OK;
  }
  bool terminal = rule.tag == X3_TAG_BOOL && rule.as.b;
  X3Value ellipsis = x3_value_invalid();
  if (!terminal &&
      package->host->builtin_value(package->host, "Ellipsis", &ellipsis) ==
          X3_STATUS_OK) {
    terminal = same_object(rule, ellipsis);
    package->host->value_release(ellipsis);
  }
  if (exclude_selector && terminal) {
    *selected = false;
  } else if (!terminal) {
    *child_selector = rule;
    return X3_STATUS_OK;
  }
  package->host->value_release(rule);
  return X3_STATUS_OK;
}

bool serialization_selector_terminal(
    PackageState* package, X3Runtime* runtime, X3Value value) {
  if (value.tag == X3_TAG_NONE ||
      (value.tag == X3_TAG_BOOL && value.as.b))
    return true;
  X3Value ellipsis = x3_value_invalid();
  const bool terminal = package->host->builtin_value(
                            package->host, "Ellipsis", &ellipsis) ==
          X3_STATUS_OK &&
      same_object(value, ellipsis);
  if (ellipsis.tag != X3_TAG_INVALID)
    package->host->value_release(ellipsis);
  return terminal;
}

bool serialization_selector_mapping(
    PackageState* package, X3Runtime* runtime, X3Value selector,
    X3Value* result) {
  if (package->host->value_object_kind(selector) == X3_OBJECT_KIND_DICT) {
    package->host->value_retain(selector);
    *result = selector;
    return true;
  }
  X3Value output = package->host->value_dict(runtime);
  X3Value iter_function = x3_value_invalid();
  X3Value iterator = x3_value_invalid();
  X3Value next_function = x3_value_invalid();
  X3Value ellipsis = x3_value_invalid();
  bool ok = output.tag != X3_TAG_INVALID &&
      package->host->builtin_value(package->host, "iter", &iter_function) ==
          X3_STATUS_OK &&
      package->host->call(
          runtime, iter_function, &selector, 1, &iterator) == X3_STATUS_OK &&
      package->host->builtin_value(package->host, "next", &next_function) ==
          X3_STATUS_OK &&
      package->host->builtin_value(package->host, "Ellipsis", &ellipsis) ==
          X3_STATUS_OK;
  while (ok) {
    X3Value item = x3_value_invalid();
    X3Value arguments[] = {iterator, package->iterator_end_sentinel};
    ok = package->host->call(
             runtime, next_function, arguments, 2, &item) == X3_STATUS_OK;
    if (!ok) {
      if (item.tag != X3_TAG_INVALID) package->host->value_release(item);
      break;
    }
    if (same_object(item, package->iterator_end_sentinel)) {
      package->host->value_release(item);
      break;
    }
    ok = package->host->dict_set_item(runtime, output, item, ellipsis) ==
        X3_STATUS_OK;
    package->host->value_release(item);
  }
  if (ellipsis.tag != X3_TAG_INVALID) package->host->value_release(ellipsis);
  if (next_function.tag != X3_TAG_INVALID)
    package->host->value_release(next_function);
  if (iterator.tag != X3_TAG_INVALID) package->host->value_release(iterator);
  if (iter_function.tag != X3_TAG_INVALID)
    package->host->value_release(iter_function);
  if (!ok) {
    if (output.tag != X3_TAG_INVALID) package->host->value_release(output);
    return false;
  }
  *result = output;
  return true;
}

bool merge_serialization_selectors(
    PackageState* package, X3CallContext* context, X3Runtime* runtime, X3Value direct,
    X3Value universal, X3Value* result, unsigned depth = 0) {
  if (depth > 32) return false;
  if (serialization_selector_terminal(package, runtime, direct) ||
      serialization_selector_terminal(package, runtime, universal)) {
    package->host->value_retain(direct);
    *result = direct;
    return true;
  }
  if (package->host->value_object_kind(direct) != X3_OBJECT_KIND_DICT ||
      package->host->value_object_kind(universal) != X3_OBJECT_KIND_DICT) {
    X3Value direct_mapping = x3_value_invalid();
    X3Value universal_mapping = x3_value_invalid();
    const bool ready = serialization_selector_mapping(
                           package, runtime, direct, &direct_mapping) &&
        serialization_selector_mapping(
            package, runtime, universal, &universal_mapping);
    const bool merged = ready && merge_serialization_selectors(
        package, context, runtime, direct_mapping, universal_mapping, result,
        depth + 1);
    if (direct_mapping.tag != X3_TAG_INVALID)
      package->host->value_release(direct_mapping);
    if (universal_mapping.tag != X3_TAG_INVALID)
      package->host->value_release(universal_mapping);
    return merged;
  }
  if (package->host->value_object_kind(direct) == X3_OBJECT_KIND_DICT &&
      package->host->value_object_kind(universal) == X3_OBJECT_KIND_DICT) {
    X3Value output = package->host->value_dict(runtime);
    uint64_t direct_count = 0;
    uint64_t universal_count = 0;
    if (output.tag == X3_TAG_INVALID ||
        package->host->len(runtime, direct, &direct_count) != X3_STATUS_OK ||
        package->host->len(runtime, universal, &universal_count) !=
            X3_STATUS_OK) {
      if (output.tag != X3_TAG_INVALID)
        package->host->value_release(output);
      return false;
    }
    for (uint64_t index = 0; index < direct_count; ++index) {
      X3Value key = x3_value_invalid();
      X3Value value = x3_value_invalid();
      const bool ok = package->host->dict_get_entry(
                          runtime, direct, index, &key, &value) ==
              X3_STATUS_OK &&
          package->host->dict_set_item(runtime, output, key, value) ==
              X3_STATUS_OK;
      if (value.tag != X3_TAG_INVALID) package->host->value_release(value);
      if (key.tag != X3_TAG_INVALID) package->host->value_release(key);
      if (!ok) {
        package->host->value_release(output);
        return false;
      }
    }
    for (uint64_t index = 0; index < universal_count; ++index) {
      X3Value key = x3_value_invalid();
      X3Value universal_value = x3_value_invalid();
      X3Value direct_value = x3_value_invalid();
      X3Value merged_value = x3_value_invalid();
      bool ok = package->host->dict_get_entry(
                    runtime, universal, index, &key, &universal_value) ==
          X3_STATUS_OK;
      if (ok && package->host->get_item(
                    runtime, direct, key, &direct_value) == X3_STATUS_OK) {
        ok = merge_serialization_selectors(
            package, context, runtime, direct_value, universal_value, &merged_value,
            depth + 1);
      } else if (ok) {
        package->host->clear_exception(context);
        package->host->value_retain(universal_value);
        merged_value = universal_value;
      }
      if (ok)
        ok = package->host->dict_set_item(
                 runtime, output, key, merged_value) == X3_STATUS_OK;
      if (merged_value.tag != X3_TAG_INVALID)
        package->host->value_release(merged_value);
      if (direct_value.tag != X3_TAG_INVALID)
        package->host->value_release(direct_value);
      if (universal_value.tag != X3_TAG_INVALID)
        package->host->value_release(universal_value);
      if (key.tag != X3_TAG_INVALID) package->host->value_release(key);
      if (!ok) {
        package->host->value_release(output);
        return false;
      }
    }
    *result = output;
    return true;
  }
  X3Value copy_method = x3_value_invalid();
  X3Value update_method = x3_value_invalid();
  X3Value combined = x3_value_invalid();
  X3Value ignored = x3_value_invalid();
  const bool merged = package->host->get_attr(
                          runtime, direct, "copy", &copy_method) ==
          X3_STATUS_OK &&
      package->host->call(runtime, copy_method, nullptr, 0, &combined) ==
          X3_STATUS_OK &&
      package->host->get_attr(runtime, combined, "update", &update_method) ==
          X3_STATUS_OK &&
      package->host->call(runtime, update_method, &universal, 1, &ignored) ==
          X3_STATUS_OK;
  if (ignored.tag != X3_TAG_INVALID) package->host->value_release(ignored);
  if (update_method.tag != X3_TAG_INVALID)
    package->host->value_release(update_method);
  if (copy_method.tag != X3_TAG_INVALID)
    package->host->value_release(copy_method);
  if (!merged) {
    if (combined.tag != X3_TAG_INVALID)
      package->host->value_release(combined);
    return false;
  }
  *result = combined;
  return true;
}

X3Status sequence_index_selector(
    PackageState* package, X3CallContext* context, X3Runtime* runtime,
    X3Value selector, uint64_t index, uint64_t count, bool exclude_selector,
    bool* selected, X3Value* child_selector) {
  *selected = !exclude_selector;
  *child_selector = x3_value_none();
  if (selector.tag == X3_TAG_NONE || selector.tag == X3_TAG_INVALID) {
    *selected = true;
    return X3_STATUS_OK;
  }

  X3Value contains_method = x3_value_invalid();
  bool operator_contains = false;
  if (package->host->get_attr(runtime, selector, "__contains__",
                              &contains_method) != X3_STATUS_OK) {
    package->host->clear_exception(context);
    X3Value type_function = x3_value_invalid();
    X3Value selector_type = x3_value_invalid();
    X3Value type_name = x3_value_invalid();
    std::string type_text;
    const bool is_dict_keys =
        package->host->builtin_value(package->host, "type", &type_function) ==
            X3_STATUS_OK &&
        package->host->call(
            runtime, type_function, &selector, 1, &selector_type) ==
            X3_STATUS_OK &&
        package->host->get_attr(
            runtime, selector_type, "__name__", &type_name) == X3_STATUS_OK &&
        string_data(package, runtime, type_name, type_text) &&
        type_text == "dict_keys";
    if (type_name.tag != X3_TAG_INVALID)
      package->host->value_release(type_name);
    if (selector_type.tag != X3_TAG_INVALID)
      package->host->value_release(selector_type);
    if (type_function.tag != X3_TAG_INVALID)
      package->host->value_release(type_function);
    if (!is_dict_keys) return X3_STATUS_ERROR;
    X3Value operator_module = x3_value_invalid();
    if (import_module(package, runtime, "operator", &operator_module) !=
            X3_STATUS_OK ||
        package->host->get_attr(
            runtime, operator_module, "contains", &contains_method) !=
            X3_STATUS_OK) {
      if (operator_module.tag != X3_TAG_INVALID)
        package->host->value_release(operator_module);
      return X3_STATUS_ERROR;
    }
    package->host->value_release(operator_module);
    operator_contains = true;
  }
  auto call_contains = [&](X3Value candidate, X3Value* answer) {
    if (!operator_contains)
      return package->host->call(
          runtime, contains_method, &candidate, 1, answer);
    X3Value arguments[] = {selector, candidate};
    return package->host->call(
        runtime, contains_method, arguments, 2, answer);
  };
  X3Value key = x3_value_int64(static_cast<int64_t>(index));
  X3Value answer = x3_value_invalid();
  bool contains = call_contains(key, &answer) ==
          X3_STATUS_OK &&
      answer.tag == X3_TAG_BOOL && answer.as.b;
  if (answer.tag != X3_TAG_INVALID) package->host->value_release(answer);
  answer = x3_value_invalid();
  if (!contains && count <= static_cast<uint64_t>(INT64_MAX)) {
    key = x3_value_int64(
        static_cast<int64_t>(index) - static_cast<int64_t>(count));
    contains = call_contains(key, &answer) ==
            X3_STATUS_OK &&
        answer.tag == X3_TAG_BOOL && answer.as.b;
    if (answer.tag != X3_TAG_INVALID) package->host->value_release(answer);
    answer = x3_value_invalid();
  }
  bool selected_by_all = false;
  X3Value all_key = x3_value_invalid();
  if (!contains) {
    all_key = package->host->value_string(runtime, "__all__");
    contains = all_key.tag != X3_TAG_INVALID &&
        call_contains(all_key, &answer) == X3_STATUS_OK &&
        answer.tag == X3_TAG_BOOL && answer.as.b;
    selected_by_all = contains;
    if (answer.tag != X3_TAG_INVALID)
      package->host->value_release(answer);
  }
  package->host->value_release(contains_method);
  if (!contains) {
    if (all_key.tag != X3_TAG_INVALID)
      package->host->value_release(all_key);
    *selected = exclude_selector;
    return X3_STATUS_OK;
  }

  *selected = !exclude_selector;
  if (package->host->value_object_kind(selector) != X3_OBJECT_KIND_DICT) {
    if (all_key.tag != X3_TAG_INVALID)
      package->host->value_release(all_key);
    return X3_STATUS_OK;
  }
  X3Value rule = x3_value_invalid();
  const X3Value rule_key = selected_by_all ? all_key : key;
  if (package->host->get_item(runtime, selector, rule_key, &rule) != X3_STATUS_OK) {
    package->host->clear_exception(context);
    if (all_key.tag != X3_TAG_INVALID)
      package->host->value_release(all_key);
    return X3_STATUS_OK;
  }
  if (all_key.tag != X3_TAG_INVALID)
    package->host->value_release(all_key);
  if (!selected_by_all) {
    X3Value universal_key = package->host->value_string(runtime, "__all__");
    X3Value universal_rule = x3_value_invalid();
    if (package->host->get_item(
            runtime, selector, universal_key, &universal_rule) ==
        X3_STATUS_OK) {
      auto terminal_rule = [&](X3Value candidate) {
        if (candidate.tag == X3_TAG_BOOL && candidate.as.b) return true;
        X3Value ellipsis_value = x3_value_invalid();
        const bool terminal =
            package->host->builtin_value(
                package->host, "Ellipsis", &ellipsis_value) == X3_STATUS_OK &&
            same_object(candidate, ellipsis_value);
        if (ellipsis_value.tag != X3_TAG_INVALID)
          package->host->value_release(ellipsis_value);
        return terminal;
      };
      const bool direct_terminal = terminal_rule(rule);
      const bool universal_terminal = terminal_rule(universal_rule);
      if (direct_terminal) {
        package->host->value_release(universal_rule);
        package->host->value_release(universal_key);
        *selected = !exclude_selector;
        package->host->value_release(rule);
        return X3_STATUS_OK;
      }
      if (!universal_terminal) {
        X3Value combined = x3_value_invalid();
        const bool merged = merge_serialization_selectors(
            package, context, runtime, rule, universal_rule, &combined);
        package->host->value_release(universal_rule);
        if (!merged) {
          package->host->value_release(rule);
          package->host->value_release(universal_key);
          return X3_STATUS_ERROR;
        }
        package->host->value_release(rule);
        rule = combined;
      } else {
        package->host->value_release(universal_rule);
      }
    } else {
      package->host->clear_exception(context);
    }
    package->host->value_release(universal_key);
  }
  bool terminal = rule.tag == X3_TAG_BOOL && rule.as.b;
  X3Value ellipsis = x3_value_invalid();
  if (!terminal &&
      package->host->builtin_value(package->host, "Ellipsis", &ellipsis) ==
          X3_STATUS_OK) {
    terminal = same_object(rule, ellipsis);
    package->host->value_release(ellipsis);
  }
  if (exclude_selector && terminal) {
    *selected = false;
    package->host->value_release(rule);
  } else if (!terminal) {
    *selected = true;
    *child_selector = rule;
  } else {
    package->host->value_release(rule);
  }
  return X3_STATUS_OK;
}

X3Status mapping_key_selector(
    PackageState* package, X3CallContext* context, X3Runtime* runtime,
    X3Value selector, X3Value key, bool exclude_selector, bool* selected,
    X3Value* child_selector) {
  *selected = !exclude_selector;
  *child_selector = x3_value_none();
  if (selector.tag == X3_TAG_NONE || selector.tag == X3_TAG_INVALID) {
    *selected = true;
    return X3_STATUS_OK;
  }
  X3Value contains_method = x3_value_invalid();
  X3Value answer = x3_value_invalid();
  bool called = package->host->get_attr(
                          runtime, selector, "__contains__",
                          &contains_method) == X3_STATUS_OK &&
      package->host->call(runtime, contains_method, &key, 1, &answer) ==
          X3_STATUS_OK;
  if (!called) {
    if (contains_method.tag != X3_TAG_INVALID)
      package->host->value_release(contains_method);
    if (answer.tag != X3_TAG_INVALID) package->host->value_release(answer);
    return X3_STATUS_ERROR;
  }
  bool contains = answer.tag == X3_TAG_BOOL && answer.as.b;
  package->host->value_release(answer);
  answer = x3_value_invalid();
  bool selected_by_all = false;
  X3Value all_key = x3_value_invalid();
  if (!contains) {
    all_key = package->host->value_string(runtime, "__all__");
    called = all_key.tag != X3_TAG_INVALID &&
        package->host->call(runtime, contains_method, &all_key, 1,
                            &answer) == X3_STATUS_OK;
    if (!called) {
      if (answer.tag != X3_TAG_INVALID)
        package->host->value_release(answer);
      if (all_key.tag != X3_TAG_INVALID)
        package->host->value_release(all_key);
      package->host->value_release(contains_method);
      return X3_STATUS_ERROR;
    }
    contains = answer.tag == X3_TAG_BOOL && answer.as.b;
    selected_by_all = contains;
    package->host->value_release(answer);
  }
  package->host->value_release(contains_method);
  if (!contains) {
    if (all_key.tag != X3_TAG_INVALID)
      package->host->value_release(all_key);
    *selected = exclude_selector;
    return X3_STATUS_OK;
  }
  *selected = !exclude_selector;
  if (package->host->value_object_kind(selector) != X3_OBJECT_KIND_DICT) {
    if (all_key.tag != X3_TAG_INVALID)
      package->host->value_release(all_key);
    return X3_STATUS_OK;
  }
  X3Value rule = x3_value_invalid();
  const X3Value rule_key = selected_by_all ? all_key : key;
  if (package->host->get_item(runtime, selector, rule_key, &rule) != X3_STATUS_OK) {
    package->host->clear_exception(context);
    if (all_key.tag != X3_TAG_INVALID)
      package->host->value_release(all_key);
    return X3_STATUS_OK;
  }
  if (all_key.tag != X3_TAG_INVALID)
    package->host->value_release(all_key);
  if (!selected_by_all) {
    X3Value universal_key = package->host->value_string(runtime, "__all__");
    X3Value universal_rule = x3_value_invalid();
    if (package->host->get_item(
            runtime, selector, universal_key, &universal_rule) ==
        X3_STATUS_OK) {
      auto terminal_rule = [&](X3Value candidate) {
        if (candidate.tag == X3_TAG_BOOL && candidate.as.b) return true;
        X3Value ellipsis_value = x3_value_invalid();
        const bool terminal =
            package->host->builtin_value(
                package->host, "Ellipsis", &ellipsis_value) == X3_STATUS_OK &&
            same_object(candidate, ellipsis_value);
        if (ellipsis_value.tag != X3_TAG_INVALID)
          package->host->value_release(ellipsis_value);
        return terminal;
      };
      const bool direct_terminal = terminal_rule(rule);
      const bool universal_terminal = terminal_rule(universal_rule);
      if (direct_terminal || universal_terminal) {
        package->host->value_release(rule);
        package->host->value_release(universal_rule);
        package->host->value_release(universal_key);
        *selected = !exclude_selector;
        return X3_STATUS_OK;
      }
      X3Value copy_method = x3_value_invalid();
      X3Value update_method = x3_value_invalid();
      X3Value combined = x3_value_invalid();
      X3Value ignored = x3_value_invalid();
      const bool merged = package->host->get_attr(
                              runtime, rule, "copy", &copy_method) ==
              X3_STATUS_OK &&
          package->host->call(
              runtime, copy_method, nullptr, 0, &combined) == X3_STATUS_OK &&
          package->host->get_attr(
              runtime, combined, "update", &update_method) == X3_STATUS_OK &&
          package->host->call(
              runtime, update_method, &universal_rule, 1, &ignored) ==
              X3_STATUS_OK;
      if (ignored.tag != X3_TAG_INVALID)
        package->host->value_release(ignored);
      if (update_method.tag != X3_TAG_INVALID)
        package->host->value_release(update_method);
      if (copy_method.tag != X3_TAG_INVALID)
        package->host->value_release(copy_method);
      package->host->value_release(universal_rule);
      if (!merged) {
        package->host->value_release(rule);
        package->host->value_release(universal_key);
        if (combined.tag != X3_TAG_INVALID)
          package->host->value_release(combined);
        return X3_STATUS_ERROR;
      }
      package->host->value_release(rule);
      rule = combined;
    } else {
      package->host->clear_exception(context);
    }
    package->host->value_release(universal_key);
  }
  bool terminal = rule.tag == X3_TAG_BOOL && rule.as.b;
  X3Value ellipsis = x3_value_invalid();
  if (!terminal &&
      package->host->builtin_value(package->host, "Ellipsis", &ellipsis) ==
          X3_STATUS_OK) {
    terminal = same_object(rule, ellipsis);
    package->host->value_release(ellipsis);
  }
  if (exclude_selector && terminal) {
    *selected = false;
    package->host->value_release(rule);
  } else if (!terminal) {
    *selected = true;
    *child_selector = rule;
  } else {
    package->host->value_release(rule);
  }
  return X3_STATUS_OK;
}

X3Status unsized_index_selector(
    PackageState* package, X3CallContext* context, X3Runtime* runtime,
    X3Value selector, uint64_t index, bool exclude_selector, bool* selected,
    X3Value* child_selector) {
  *selected = !exclude_selector;
  *child_selector = x3_value_none();
  if (selector.tag == X3_TAG_NONE || selector.tag == X3_TAG_INVALID) {
    *selected = true;
    return X3_STATUS_OK;
  }
  X3Value contains_method = x3_value_invalid();
  X3Value answer = x3_value_invalid();
  const X3Value key = x3_value_uint64(index);
  const bool called = package->host->get_attr(
                          runtime, selector, "__contains__",
                          &contains_method) == X3_STATUS_OK &&
      package->host->call(runtime, contains_method, &key, 1, &answer) ==
          X3_STATUS_OK;
  if (contains_method.tag != X3_TAG_INVALID)
    package->host->value_release(contains_method);
  if (!called) {
    if (answer.tag != X3_TAG_INVALID) package->host->value_release(answer);
    return X3_STATUS_ERROR;
  }
  const bool contains = answer.tag == X3_TAG_BOOL && answer.as.b;
  package->host->value_release(answer);
  if (!contains) {
    *selected = exclude_selector;
    return X3_STATUS_OK;
  }
  *selected = !exclude_selector;
  if (package->host->value_object_kind(selector) != X3_OBJECT_KIND_DICT)
    return X3_STATUS_OK;
  X3Value rule = x3_value_invalid();
  if (package->host->get_item(runtime, selector, key, &rule) != X3_STATUS_OK) {
    package->host->clear_exception(context);
    return X3_STATUS_OK;
  }
  bool terminal = rule.tag == X3_TAG_BOOL && rule.as.b;
  X3Value ellipsis = x3_value_invalid();
  if (!terminal && package->host->builtin_value(
                       package->host, "Ellipsis", &ellipsis) ==
                       X3_STATUS_OK) {
    terminal = same_object(rule, ellipsis);
    package->host->value_release(ellipsis);
  }
  if (exclude_selector && terminal) {
    *selected = false;
    package->host->value_release(rule);
  } else if (!terminal) {
    *selected = true;
    *child_selector = rule;
  } else {
    package->host->value_release(rule);
  }
  return X3_STATUS_OK;
}

X3Status unsized_index_selection(
    PackageState* package, X3CallContext* context, X3Runtime* runtime,
    X3Value schema_include, X3Value schema_exclude, X3Value include,
    X3Value exclude, uint64_t index, bool* selected,
    X3Value* child_include, X3Value* child_exclude) {
  const bool has_schema_include =
      schema_include.tag != X3_TAG_NONE &&
      schema_include.tag != X3_TAG_INVALID;
  const bool has_runtime_include =
      include.tag != X3_TAG_NONE && include.tag != X3_TAG_INVALID;
  bool schema_selected = true;
  bool runtime_selected = true;
  X3Value ignored = x3_value_none();
  if (has_schema_include && unsized_index_selector(
                                package, context, runtime, schema_include,
                                index, false, &schema_selected,
                                &ignored) != X3_STATUS_OK) {
    package->host->value_release(ignored);
    return X3_STATUS_ERROR;
  }
  package->host->value_release(ignored);
  if (has_runtime_include && unsized_index_selector(
                                 package, context, runtime, include, index,
                                 false, &runtime_selected,
                                 child_include) != X3_STATUS_OK)
    return X3_STATUS_ERROR;
  *selected = has_schema_include || has_runtime_include
      ? (has_schema_include && schema_selected) ||
            (has_runtime_include && runtime_selected)
      : true;
  bool exclusion_selected = true;
  ignored = x3_value_none();
  if (*selected && !(has_runtime_include && runtime_selected) &&
      schema_exclude.tag != X3_TAG_NONE &&
      schema_exclude.tag != X3_TAG_INVALID &&
      unsized_index_selector(
          package, context, runtime, schema_exclude, index, true,
          &exclusion_selected, &ignored) != X3_STATUS_OK) {
    package->host->value_release(ignored);
    return X3_STATUS_ERROR;
  }
  package->host->value_release(ignored);
  *selected = *selected && exclusion_selected;
  exclusion_selected = true;
  if (*selected && unsized_index_selector(
                       package, context, runtime, exclude, index, true,
                       &exclusion_selected, child_exclude) != X3_STATUS_OK)
    return X3_STATUS_ERROR;
  *selected = *selected && exclusion_selected;
  return X3_STATUS_OK;
}

X3Status sized_index_selection(
    PackageState* package, X3CallContext* context, X3Runtime* runtime,
    X3Value schema_include, X3Value schema_exclude, X3Value include,
    X3Value exclude, uint64_t index, uint64_t count, bool* selected,
    X3Value* child_include, X3Value* child_exclude) {
  const bool has_schema_include =
      schema_include.tag != X3_TAG_NONE &&
      schema_include.tag != X3_TAG_INVALID;
  const bool has_runtime_include =
      include.tag != X3_TAG_NONE && include.tag != X3_TAG_INVALID;
  bool schema_selected = true;
  bool runtime_selected = true;
  X3Value ignored = x3_value_none();
  if (has_schema_include && sequence_index_selector(
                                package, context, runtime, schema_include,
                                index, count, false, &schema_selected,
                                &ignored) != X3_STATUS_OK) {
    package->host->value_release(ignored);
    return X3_STATUS_ERROR;
  }
  package->host->value_release(ignored);
  if (has_runtime_include && sequence_index_selector(
                                 package, context, runtime, include, index,
                                 count, false, &runtime_selected,
                                 child_include) != X3_STATUS_OK)
    return X3_STATUS_ERROR;
  *selected = has_schema_include || has_runtime_include
      ? (has_schema_include && schema_selected) ||
            (has_runtime_include && runtime_selected)
      : true;
  bool exclusion_selected = true;
  ignored = x3_value_none();
  if (*selected && !(has_runtime_include && runtime_selected) &&
      schema_exclude.tag != X3_TAG_NONE &&
      schema_exclude.tag != X3_TAG_INVALID &&
      sequence_index_selector(
          package, context, runtime, schema_exclude, index, count, true,
          &exclusion_selected, &ignored) != X3_STATUS_OK) {
    package->host->value_release(ignored);
    return X3_STATUS_ERROR;
  }
  package->host->value_release(ignored);
  *selected = *selected && exclusion_selected;
  exclusion_selected = true;
  if (*selected && sequence_index_selector(
                       package, context, runtime, exclude, index, count,
                       true, &exclusion_selected,
                       child_exclude) != X3_STATUS_OK)
    return X3_STATUS_ERROR;
  *selected = *selected && exclusion_selected;
  return X3_STATUS_OK;
}

X3Status validate_sized_selector(
    PackageState* package, X3CallContext* context, X3Runtime* runtime,
    X3Value selector, const char* argument_name) {
  if (selector.tag == X3_TAG_NONE || selector.tag == X3_TAG_INVALID)
    return X3_STATUS_OK;
  X3Value contains = x3_value_invalid();
  if (package->host->get_attr(
          runtime, selector, "__contains__", &contains) == X3_STATUS_OK) {
    const bool usable = contains.tag != X3_TAG_NONE;
    package->host->value_release(contains);
    if (usable) return X3_STATUS_OK;
  } else {
    package->host->clear_exception(context);
  }
  X3Value type_function = x3_value_invalid();
  X3Value selector_type = x3_value_invalid();
  X3Value name = x3_value_invalid();
  std::string type_name;
  const bool is_dict_keys =
      package->host->builtin_value(package->host, "type", &type_function) ==
          X3_STATUS_OK &&
      package->host->call(
          runtime, type_function, &selector, 1, &selector_type) ==
          X3_STATUS_OK &&
      package->host->get_attr(runtime, selector_type, "__name__", &name) ==
          X3_STATUS_OK &&
      string_data(package, runtime, name, type_name) &&
      type_name == "dict_keys";
  if (name.tag != X3_TAG_INVALID) package->host->value_release(name);
  if (selector_type.tag != X3_TAG_INVALID)
    package->host->value_release(selector_type);
  if (type_function.tag != X3_TAG_INVALID)
    package->host->value_release(type_function);
  if (is_dict_keys) return X3_STATUS_OK;
  const std::string message = "`" + std::string(argument_name) +
      "` argument must be a set or dict.";
  return package->host->raise_class_error(
      context, "TypeError", message.c_str());
}

X3Status validate_unsized_selector(
    PackageState* package, X3CallContext* context, X3Runtime* runtime,
    X3Value selector) {
  if (selector.tag == X3_TAG_NONE || selector.tag == X3_TAG_INVALID)
    return X3_STATUS_OK;
  X3Value iter_function = x3_value_invalid();
  X3Value iterator = x3_value_invalid();
  X3Value next_function = x3_value_invalid();
  if (package->host->builtin_value(
          package->host, "iter", &iter_function) != X3_STATUS_OK ||
      package->host->call(
          runtime, iter_function, &selector, 1, &iterator) != X3_STATUS_OK ||
      package->host->builtin_value(
          package->host, "next", &next_function) != X3_STATUS_OK) {
    if (next_function.tag != X3_TAG_INVALID)
      package->host->value_release(next_function);
    if (iterator.tag != X3_TAG_INVALID)
      package->host->value_release(iterator);
    if (iter_function.tag != X3_TAG_INVALID)
      package->host->value_release(iter_function);
    return X3_STATUS_ERROR;
  }
  package->host->value_release(iter_function);
  bool negative = false;
  while (true) {
    X3Value item = x3_value_invalid();
    X3Value arguments[] = {iterator, package->iterator_end_sentinel};
    if (package->host->call(
            runtime, next_function, arguments, 2, &item) != X3_STATUS_OK) {
      package->host->value_release(next_function);
      package->host->value_release(iterator);
      return X3_STATUS_ERROR;
    }
    if (same_object(item, package->iterator_end_sentinel)) {
      package->host->value_release(item);
      break;
    }
    negative = item.tag == X3_TAG_INT64 && item.as.i64 < 0;
    package->host->value_release(item);
    if (negative) break;
  }
  package->host->value_release(next_function);
  package->host->value_release(iterator);
  if (negative)
    return package->host->raise_class_error(
        context, "ValueError",
        "Negative indices cannot be used to exclude items on unsized iterables");
  return X3_STATUS_OK;
}

X3Status copy_default(PackageState* package, X3Runtime* runtime, X3Value value, X3Value* result) {
  const auto kind = package->host->value_object_kind(value);
  if (kind != X3_OBJECT_KIND_DICT && kind != X3_OBJECT_KIND_LIST) {
    package->host->value_retain(value);
    *result = value;
    return X3_STATUS_OK;
  }
  X3Value copy = x3_value_invalid();
  if (package->host->get_attr(runtime, value, "copy", &copy) != X3_STATUS_OK) return X3_STATUS_ERROR;
  const auto status = package->host->call(runtime, copy, nullptr, 0, result);
  package->host->value_release(copy);
  return status;
}

